return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-06 01:48+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Pumunta sa Plugin Search','Activate %s' => 'I-activate ang %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>Ang %1$s</strong> ay nangangailangan ng <strong>%2$s</strong> na mai-install at ma-activate. <a href="%4$s">%3$s</a>','Enter your code here' => 'Ilagay ang iyong code dito','Add %s' => 'Magdagdag ng %s','Remove' => 'Alisin','Order number and receipt will be sent to this email address.' => 'Ang numero ng order at resibo ay ipapadala sa email address na ito.','Apartment, unit, building, floor, etc.' => 'Apartment, unit, gusali, sahig, atbp.','Shipping phone' => 'Telepono sa pagpapadala','Only used for shipping-related questions.' => 'Ginagamit lang para sa mga tanong na nauugnay sa pagpapadala.','Single step' => 'Isang hakbang','Click to go to the order summary' => 'I-click upang pumunta sa buod ng order','Cart total:' => 'Kabuuan ng cart:','Proceed to %s' => 'Magpatuloy sa %s','Proceed to contact' => 'Magpatuloy sa pakikipag-ugnayan','Proceed to shipping' => 'Magpatuloy sa pagpapadala','Proceed to billing' => 'Magpatuloy sa pagsingil','Proceed to payment' => 'Magpatuloy sa pagbabayad','Shipping method' => 'Paraan ng pagpapadala','Additional notes' => 'Mga karagdagang tala','Payment method' => 'Paraan ng pagbabayad','Step %1$s of %2$s' => 'Hakbang %1$s ng %2$s','Change: %s' => 'Baguhin: %s','Not selected yet.' => 'Hindi pa napili.','Same as shipping address' => 'Pareho sa address ng pagpapadala','Same as billing address' => 'Pareho sa billing address','Order summary' => 'Buod ng order','Edit cart' => 'I-edit ang cart','Did you mean %s?' => 'Ang ibig mo bang sabihin ay %s?','Change email address to: {suggestion-value}' => 'Baguhin ang email address sa: {suggestion-value}','This is a required field.' => 'Ito ay isang kinakailangang field.','This is not a valid email address.' => 'Ito ay hindi isang wastong email address.','This field does not match the related field value.' => 'Hindi tumutugma ang field na ito sa nauugnay na value ng field.','The CPF number "{cpf_number}" is invalid.' => 'Ang CPF number na &quot;{cpf_number}&quot; ay hindi wasto.','The CNPJ number "{cnpj_number}" is invalid.' => 'Ang CNPJ number na &quot;{cnpj_number}&quot; ay hindi wasto.','(Required)' => '(Kinakailangan)','Checkout Header - Desktop' => 'Checkout Header - Desktop','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Ipakita ang mga widget sa checkout header para sa malalaking screen. Ipinapakita lamang kung gumagamit ng checkout header ng plugin.','Checkout Header - Mobile' => 'Checkout Header - Mobile','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Ipakita ang mga widget sa ibaba ng checkout header para sa mga mobile device. Ipinapakita lamang kung gumagamit ng checkout header ng plugin.','Checkout Sidebar' => 'Checkout Sidebar','Display widgets on the checkout sidebar after the order summary.' => 'Ipakita ang mga widget sa checkout sidebar pagkatapos ng buod ng order.','Checkout Order Summary' => 'Buod ng Order ng Checkout','Display widgets inside the order summary at the checkout page.' => 'Ipakita ang mga widget sa loob ng buod ng order sa pahina ng pag-checkout.','Checkout Below Place Order' => 'Checkout sa ibaba ng Place Order','Display widgets below the place order button at the checkout page.' => 'Ipakita ang mga widget sa ibaba ng place order button sa pahina ng pag-checkout.','Checkout Footer' => 'Checkout Footer','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Ipakita ang mga widget sa checkout footer. Ipinapakita lamang kung gumagamit ng checkout footer ng plugin.','Classic' => 'Classic','Boxed' => 'Naka-box','Split' => 'Hatiin','Minimalist' => 'Minimalist','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'Mga plugin ng Fluid Checkout at Delivery Date ng CodeRockz','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Nakita namin na ginagamit mo ang mga plugin na Delivery &amp; Pickup Date Time para sa WooCommerce (libre at PRO) ng CodeRockz. Ang pagsasama sa mga plugin na ito ay inilipat sa Fluid Checkout PRO.</p>','Upgrade to PRO' => 'Mag-upgrade sa PRO','Fluid Checkout database updated successfully' => 'Matagumpay na na-update ang database ng Fluid Checkout','The database changes where applied successfully.' => 'Ang database ay nagbabago kung saan matagumpay na nailapat.','Dismiss' => 'I-dismiss','Fluid Checkout database update' => 'Pag-update ng database ng Fluid Checkout','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Ang ilang mga pagbabago sa database ay kinakailangan. Tulad ng anumang pag-update, inirerekomenda namin sa iyo na <strong>kumuha ng buong backup ng iyong website bago magpatuloy</strong> .','Update database' => 'I-update ang database','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Ang Fluid Checkout ay hindi tugma sa layout ng checkout ng Divi Builder','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Kailangan ng Fluid Checkout ang klasikong WooCommerce shortcode-based na checkout form upang gumana. Kapag ginagamit ang Divi Builder upang i-customize ang hitsura at pakiramdam ng pahina ng pag-checkout, ang mga klasikong shortcode ay pinapalitan ng mga custom na widget mula sa Divi Builder para sa bawat bahagi ng pahina ng pag-checkout. Ang mga custom na widget na ito ay hindi tugma sa Fluid Checkout.</p><p> Paki-edit ang iyong pahina ng pag-checkout na pinapalitan ang mga widget ng Divi Builder ng isang widget ng teksto na naglalaman ng shortcode <code>[woocommerce_checkout]</code> .</p>','Edit the checkout page' => 'I-edit ang pahina ng pag-checkout','Read the documentation.' => 'Basahin ang dokumentasyon.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Kailangang i-disable ang feature na Germanized PRO multistep checkout kapag gumagamit ng Fluid Checkout','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Kapag gumagamit ng Fluid Checkout, ang multistep na feature mula sa Germanized PRO plugin ay nagiging hindi na kailangan at maaaring magdulot ng <strong>mga kritikal na error habang pinoproseso ang mga bagong order</strong> . Mangyaring huwag paganahin ang tampok na Germanized PRO multistep checkout sa mga setting ng plugin.','Go to Germanized settings' => 'Pumunta sa mga setting ng Germanized','Thanks for choosing Fluid Checkout!' => 'Salamat sa pagpili ng Fluid Checkout!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Matagal mo nang ginagamit ang plugin. Paano mo ito gusto sa ngayon?<br> Mangyaring bigyan kami ng mabilis na rating, pinahahalagahan namin ang bawat piraso ng feedback at hinihikayat kami nitong patuloy na pahusayin ang plugin :)','Rate the plugin' => 'I-rate ang plugin','I need help!' => 'Kailangan ko ng tulong!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Maaaring hindi gumana ang ilang feature ng WooCommerce Checkout Manager ng Quadlayers gaya ng inaasahan kapag ginagamit ito sa Fluid Checkout. Basahin <a href="%s">ang aming dokumentasyon</a> para sa higit pang impormasyon at mga alternatibong solusyon.','Read documentation' => 'Basahin ang dokumentasyon','Don\'t show this again' => 'Huwag mo na itong ipakitang muli','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'Higit pang mga template ng disenyo','Optimized cart page' => 'Na-optimize na pahina ng cart','Optimized order received / thank you page' => 'Natanggap ang na-optimize na order / pahina ng salamat','Edit cart contents at checkout page' => 'I-edit ang mga nilalaman ng cart sa pahina ng pag-checkout','Account matching / user matching' => 'Pagtutugma ng account / pagtutugma ng user','Trust symbols on the cart and thank you pages' => 'Mga simbolo ng tiwala sa cart at mga pahina ng pasasalamat','More positions for the coupon code on the checkout page' => 'Higit pang mga posisyon para sa coupon code sa pahina ng pag-checkout','International phone numbers' => 'Mga internasyonal na numero ng telepono','Gift messages and packing slips' => 'Mga mensahe ng regalo at packing slip','Local pickup and in-store collection' => 'Lokal na pickup at in-store na koleksyon','EU-VAT Assistant' => 'Katulong ng EU-VAT','I already have it – Hide this offer' => 'Mayroon na ako nito - Itago ang alok na ito','Activated' => 'Na-activate','Address book' => 'Address book','Select an image' => 'Pumili ng larawan','Cart layout' => 'Layout ng cart','Cart optimizations' => 'Mga pag-optimize ng cart','Enable cart page optimizations' => 'Paganahin ang mga pag-optimize ng pahina ng cart','Header and footer template' => 'Template ng header at footer','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Kinokontrol kung gagamitin ang header at footer ng page na walang distraction o panatilihin ang header at footer ng kasalukuyang aktibong tema.','Distraction free header and footer' => 'Walang distraction na header at footer','Theme\'s header and footer' => 'Header at footer ng tema','Cart elements' => 'Mga elemento ng cart','Make the order summary stay visible on the cart page while scrolling' => 'Gawing manatiling nakikita ang buod ng order sa page ng cart habang nag-i-scroll','Coupon codes' => 'Mga code ng kupon','Hidden' => 'Nakatago','Before the cart items section' => 'Bago ang seksyon ng mga item sa cart','Inside the cart items section' => 'Sa loob ng seksyon ng mga item sa cart','After the cart items section' => 'Pagkatapos ng seksyon ng mga item sa cart','Before the shipping section' => 'Bago ang shipping section','After the shipping section' => 'Pagkatapos ng shipping section','Before the order summary' => 'Bago ang buod ng order','Inside the order summary' => 'Sa loob ng buod ng order','Before the order totals' => 'Bago mabuo ang order','After the order totals' => 'Matapos ang kabuuan ng order','After the order summary' => 'Pagkatapos ng buod ng order','Shipping' => 'Pagpapadala','Select position where to display the shipping costs and calculator on the cart page.' => 'Piliin ang posisyon kung saan ipapakita ang mga gastos sa pagpapadala at calculator sa page ng cart.','Display as a cart section' => 'Ipakita bilang seksyon ng cart','Cross-sells' => 'Cross-sells','Select position where to display the cross-sells section on the cart page.' => 'Piliin ang posisyon kung saan ipapakita ang seksyong cross-sells sa page ng cart.','Before the cart actions' => 'Bago kumilos ang cart','After the cart actions' => 'Pagkatapos ng mga pagkilos ng cart','Layout of cross-sell items on the cart page.' => 'Layout ng mga cross-sell na item sa page ng cart.','Optimized horizontal cross-sells layout' => 'Na-optimize na layout ng pahalang na cross-sells','Theme\'s cross-sells layout' => 'Layout ng cross-sells ng tema','Number of cross-sell items to display on the cart page' => 'Bilang ng mga cross-sell na item na ipapakita sa page ng cart','Add widget areas to the cart page' => 'Magdagdag ng mga lugar ng widget sa pahina ng cart','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Ginagamit ang mga widget area na ito upang magdagdag ng mga simbolo ng trust at trust badge sa page ng cart.','Checkout' => 'Checkout','Checkout layout' => 'Layout ng checkout','Design template' => 'Template ng disenyo','Dark mode' => 'Dark mode','Enable dark mode' => 'Paganahin ang dark mode','Logo image' => 'Larawan ng logo','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Pumili ng larawang ipapakita sa header ng pahina ng pag-checkout. Nalalapat lamang kapag ginagamit ang walang distraction na header at footer.','Header background color' => 'Kulay ng background ng header','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Pumili ng kulay ng background para sa header ng pahina ng pag-checkout. Nalalapat lang kapag ginagamit ang walang distraction na header at footer.','HTML color value. ie: #f3f3f3' => 'Halaga ng kulay ng HTML. ibig sabihin: #f3f3f3','Page background color' => 'Kulay ng background ng page','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Pumili ng kulay ng background para sa pahina ng pag-checkout. Ang kulay ay inilalapat sa elemento <em>ng katawan</em> .','Footer background color' => 'Kulay ng background ng footer','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Pumili ng kulay ng background para sa footer ng pahina ng pag-checkout. Nalalapat lamang kapag ginagamit ang walang distraction na header at footer.','Progress bar' => 'Progress bar','Display the checkout progress bar when using multi-step checkout layout' => 'Ipakita ang checkout progress bar kapag gumagamit ng multi-step na layout ng checkout','Make the checkout progress bar stay visible while scrolling' => 'Gawing manatiling nakikita ang progress bar ng pag-checkout habang nag-i-scroll','Express checkout' => 'Express checkout','Enable the express checkout section' => 'Paganahin ang seksyon ng express checkout','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Ipinapakita ang seksyon ng express checkout sa pag-checkout kapag pinagana ang feature na ito sa mga sinusuportahang gateway ng pagbabayad.','Display express checkout buttons in one line for larger screens' => 'Ipakita ang mga pindutan ng express checkout sa isang linya para sa mas malalaking screen','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Huwag pansinin ang mga karagdagang kinakailangang field sa pag-checkout kapag nagbabayad gamit ang isang katugmang gateway ng pagbabayad ng express checkout','Make the order summary stay visible while scrolling' => 'Gawing manatiling nakikita ang buod ng order habang nag-i-scroll','Choose a background color for the order summary section.' => 'Pumili ng kulay ng background para sa seksyon ng buod ng order.','Highlight the order totals row in the order summary table' => 'I-highlight ang hilera ng mga kabuuan ng order sa talahanayan ng buod ng order','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Pinaka-kapaki-pakinabang kapag ang seksyon ng buod ng order ay walang naka-highlight na kulay ng background. Maaari ding mag-apply sa Cart, Order Received at View Order page kapag gumagamit ng Fluid Checkout PRO.','Action link on the order summary at checkout.' => 'Link ng aksyon sa buod ng order sa pag-checkout.','Edit cart link' => 'I-edit ang link ng cart','Cart items count' => 'Bilang ng mga item sa cart','Link to shop page' => 'Link sa page ng shop','Cart items' => 'Mga item sa cart','Hide cart items errors at the checkout page' => 'Itago ang mga error sa cart item sa page ng pag-checkout','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Huwag ipakita ang mensahe ng mga error sa cart item sa tuktok ng pahina ng pag-checkout. Kapag isinusumite ang form ng pag-checkout upang kumpletuhin ang pagbili, ang mga mensahe ng error na ito ay palaging ipapakita.','Place order' => 'Maglagay ng order','Define the position to display "Place order" and terms checkbox section.' => 'Tukuyin ang posisyon upang ipakita ang &quot;Place order&quot; at mga termino sa checkbox na seksyon.','Some options might not be compatible with some plugins and themes.' => 'Maaaring hindi tugma ang ilang opsyon sa ilang plugin at tema.','Below the payment section' => 'Sa ibaba ng seksyon ng pagbabayad','Below the order summary' => 'Sa ibaba ng buod ng order','Both below the payment section and the order summary' => 'Parehong nasa ibaba ng seksyon ng pagbabayad at ang buod ng order','Add widget areas to the checkout page' => 'Magdagdag ng mga lugar ng widget sa pahina ng pag-checkout','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Ginagamit ang mga widget area na ito upang magdagdag ng mga simbolo ng tiwala at mga badge ng tiwala sa pahina ng pag-checkout.','Display the coupon codes section title' => 'Ipakita ang pamagat ng seksyon ng mga code ng kupon','Select position where to display the coupon codes section on the checkout page.' => 'Piliin ang posisyon kung saan ipapakita ang seksyon ng mga code ng kupon sa pahina ng pag-checkout.','Before the checkout steps' => 'Bago ang mga hakbang sa pag-checkout','As a substep before payment methods' => 'Bilang isang substep bago ang mga paraan ng pagbabayad','As a substep after payment methods' => 'Bilang isang substep pagkatapos ng mga paraan ng pagbabayad','Default button style' => 'Default na istilo ng button','"Add" link button' => '&quot;Magdagdag&quot; na pindutan ng link','Checkout fields' => 'Mga field ng checkout','Optional fields' => 'Opsyonal na mga patlang','Hide optional fields behind a link button' => 'Itago ang mga opsyonal na field sa likod ng isang link button','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Inirerekomenda na panatilihing naka-check ang opsyong ito upang mabawasan ang bilang ng mga bukas na input field, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">basahin ang pananaliksik</a> .','Do not hide "Address line 2" fields behind a link button' => 'Huwag itago ang mga field na &quot;Address line 2&quot; sa likod ng isang link button','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Inirerekomenda lamang kapag ang karamihan sa mga customer ay talagang nangangailangan ng field na &quot;Address line 2&quot;, o kapag ang pagkuha ng tamang address sa pagpapadala ay mahalaga (ibig sabihin, kung naghahatid ng pagkain at iba pang nabubulok na produkto).','Billing address' => 'Billing address','Select position where to display the billing address section on the checkout page.' => 'Piliin ang posisyon kung saan ipapakita ang seksyon ng billing address sa page ng pag-checkout.','As a step before shipping' => 'Bilang isang hakbang bago ipadala','As a sub-step before the shipping address section' => 'Bilang isang sub-step bago ang seksyon ng address ng pagpapadala','As a sub-step after the shipping address section' => 'Bilang isang sub-step pagkatapos ng seksyon ng address sa pagpapadala','As a step after shipping' => 'Bilang isang hakbang pagkatapos ng pagpapadala','As a sub-step before the payment section' => 'Bilang isang sub-step bago ang seksyon ng pagbabayad','Force billing and shipping addresses to the same (single section)' => 'Pilitin ang pagsingil at mga address sa pagpapadala sa pareho (iisang seksyon)','Checkbox for "Same as shipping/billing address" checked by default' => 'Ang checkbox para sa &quot;Kapareho ng shipping/billing address&quot; ay may check bilang default','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'Ang checkbox na &quot;Kapareho ng address sa pagpapadala&quot; ay magsisimula bilang naka-check bilang default kapag ang seksyon ng address sa pagpapadala ay unang ipinakita.<br> Ang checkbox na &quot;Kapareho ng billing address&quot; ay magsisimula bilang naka-check bilang default kapag ang seksyon ng billing address ay unang ipinakita.<br> Inirerekomenda na iwanang naka-check ang opsyong ito upang makabuluhang bawasan ang bilang ng mga bukas na input field sa pag-checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">basahin ang pananaliksik</a> .','Highlight the billing address section in the checkout form' => 'I-highlight ang seksyon ng billing address sa form ng pag-checkout','Shipping address' => 'Address ng pagpapadala','Highlight the shipping address section in the checkout form' => 'I-highlight ang seksyon ng address ng pagpapadala sa form ng pag-checkout','Shipping methods' => 'Mga paraan ng pagpapadala','Choose in which position to display the shipping methods section.' => 'Piliin kung saang posisyon ipapakita ang seksyon ng mga paraan ng pagpapadala.','Before shipping address' => 'Bago ang address ng pagpapadala','After shipping address' => 'Pagkatapos ng address ng pagpapadala','Local pickup' => 'Lokal na pickup','Removes shipping address section when a local pickup shipping method is selected.' => 'Inaalis ang seksyon ng address sa pagpapadala kapag napili ang isang lokal na paraan ng pagpapadala ng pickup.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Pinapalitan ang address ng pagpapadala ng lokasyon ng pickup point kapag napili ang isang lokal na paraan ng pagpapadala ng pickup.','Choose which address to save as the shipping address for local pickup orders.' => 'Piliin kung aling address ang ise-save bilang address sa pagpapadala para sa mga lokal na pickup order.','Save the selected pickup location' => 'I-save ang napiling lokasyon ng pickup','Save same as the billing address' => 'I-save katulad ng billing address','Do not save any shipping address' => 'Huwag i-save ang anumang address sa pagpapadala','Company name field for shipping address' => 'Field ng pangalan ng kumpanya para sa address ng pagpapadala','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Baguhin ang visibility para sa field ng pangalan ng kumpanya para sa seksyon ng address ng pagpapadala sa form ng pag-checkout.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Kung nakatakda ang field bilang &quot;opsyonal&quot;, na siyang default na estado ng visibility, walang mga pagbabagong ilalapat upang hayaan ang ibang mga plugin na maglapat ng anumang mga pagbabagong kailangan nila.','Hidden (remove field)' => 'Nakatago (alisin ang field)','Optional' => 'Opsyonal','Required' => 'Kinakailangan','Add shipping phone field to the checkout form.' => 'Magdagdag ng field ng telepono sa pagpapadala sa form ng pag-checkout.','Choose in which step to display the shipping phone field.' => 'Piliin kung saang hakbang ipapakita ang field ng telepono sa pagpapadala.','Contact step' => 'Hakbang sa pakikipag-ugnayan','Billing phone' => 'Telepono sa pagsingil','Add billing phone field to the checkout form.' => 'Magdagdag ng field ng telepono sa pagsingil sa form ng pag-checkout.','Choose in which step to display the billing phone field.' => 'Piliin kung saang hakbang ipapakita ang field ng telepono sa pagsingil.','Show country code beside the flag' => 'Ipakita ang code ng bansa sa tabi ng bandila','Show an example of a valid phone number inside phone fields' => 'Magpakita ng halimbawa ng wastong numero ng telepono sa loob ng mga field ng telepono','Do not change placeholders' => 'Huwag magpalit ng mga placeholder','Show if not defined' => 'Ipakita kung hindi tinukoy','Always show' => 'Palaging ipakita','Order notes' => 'Mga tala ng order','Define the visibility of the additional order notes field.' => 'Tukuyin ang visibility ng field ng karagdagang mga tala ng order.','Gift options' => 'Mga pagpipilian sa regalo','Allow customers to add a gift message and other gift related options to the order.' => 'Payagan ang mga customer na magdagdag ng mensahe ng regalo at iba pang mga opsyon na nauugnay sa regalo sa order.','Display the gift message as part of the order details table instead of a separate section' => 'Ipakita ang mensahe ng regalo bilang bahagi ng talahanayan ng mga detalye ng order sa halip na isang hiwalay na seksyon','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Nakakaapekto ang opsyong ito sa page ng kumpirmasyon ng order (pahina ng salamat) at mga detalye ng order sa mga page ng account, email at packing slip.','Account matching' => 'Pagtutugma ng account','Enable the account matching feature' => 'Paganahin ang tampok na pagtutugma ng account','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'Iugnay ang mga order ng bisitang customer sa kanilang kasalukuyang account kapag mayroon nang account kasama ang mga detalye ng contact ng customer.','Display message when an account exists with the email address provided' => 'Ipakita ang mensahe kapag may account na may ibinigay na email address','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Pinapalitan ang mga field ng paggawa ng account ng notification at opsyong mag-log in. Sa ilang konteksto, maaaring irekomendang iwanang naka-disable ang opsyong ito upang maprotektahan ang privacy ng mga customer.','Dashboard' => 'Dashboard','Integrations' => 'Mga pagsasama','License keys' => 'Mga susi ng lisensya','Visit our website for more information about our plugins and add-ons.' => 'Bisitahin ang aming website para sa higit pang impormasyon tungkol sa aming mga plugin at add-on.','Order pay page' => 'Pahina ng pagbabayad ng order','Order pay' => 'Bayad sa order','Enable order pay page optimizations' => 'Paganahin ang mga pag-optimize ng page ng pagbabayad ng order','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Binabago ang layout ng page ng pagbabayad ng order para sa mga umiiral nang order na nakabinbing bayad mula sa customer.','Add widget areas to the order pay page' => 'Magdagdag ng mga lugar ng widget sa page ng pagbabayad ng order','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Ginagamit ang mga widget area na ito upang magdagdag ng mga simbolo ng tiwala at mga badge ng tiwala sa page ng pagbabayad ng order.','Thank you page & order details layout' => 'Salamat page at layout ng mga detalye ng order','Order details optimizations' => 'Mga pag-optimize ng mga detalye ng order','Enable thank you page and order details optimizations' => 'Paganahin ang pahina ng pasasalamat at pag-optimize ng mga detalye ng order','Changes the layout of order details on the thank you page and account pages.' => 'Binabago ang layout ng mga detalye ng order sa pahina ng pasasalamat at mga pahina ng account.','Enable order details customizations on email notifications' => 'Paganahin ang mga pag-customize ng mga detalye ng order sa mga notification sa email','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Ipakita ang mga bagong seksyon at baguhin ang pagkakasunud-sunod ng mga seksyon sa mga notification sa email. Ang mga istilo ng mga detalye ng order sa mga notification sa email ay nananatiling hindi nagbabago.','Thank you page' => 'Salamat page','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Ang mga opsyong ito ay nakakaapekto sa pahina ng pasasalamat, na kilala rin bilang natanggap na order o mga pahina ng pagkumpirma ng order.','Order details layout' => 'Layout ng mga detalye ng order','Display the order details with wide layout on the thank you page' => 'Ipakita ang mga detalye ng order na may malawak na layout sa pahina ng pasasalamat','Add widget areas to the thank you page' => 'Magdagdag ng mga lugar ng widget sa pahina ng pasasalamat','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Ginagamit ang mga widget na lugar na ito upang magdagdag ng mga simbolo ng tiwala at mga badge ng tiwala sa pahina ng pasasalamat.','Order actions' => 'Mag-order ng mga aksyon','Choose in which position to display the order actions.' => 'Piliin kung saang posisyon ipapakita ang mga pagkilos ng pagkakasunud-sunod.','Inside the order overview' => 'Sa loob ng pangkalahatang-ideya ng order','After the order overview' => 'Pagkatapos ng pangkalahatang-ideya ng order','After order sections' => 'Pagkatapos ng mga seksyon ng order','Order status' => 'Katayuan ng order','Display the order status progress bar' => 'Ipakita ang progress bar ng status ng order','Choose in which position to display the section.' => 'Piliin kung saang posisyon ipapakita ang seksyon.','After the order overview and payment instructions' => 'Pagkatapos ng pangkalahatang-ideya ng order at mga tagubilin sa pagbabayad','Before the order items section' => 'Bago ang seksyon ng mga item ng order','Inside the order items section' => 'Sa loob ng seksyon ng mga item ng order','After the order items section' => 'Pagkatapos ng seksyon ng mga item ng order','On the sidebar' => 'Sa sidebar','Order downloads' => 'Mag-order ng mga pag-download','Gift message' => 'Mensahe ng regalo','Tools' => 'Mga gamit','Troubleshooting' => 'Pag-troubleshoot','Debug options' => 'Mga opsyon sa pag-debug','Debug mode' => 'Debug mode','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Ang paggamit ng debug mode ay nakakaapekto sa pagganap ng website. Gamitin lamang ang opsyong ito habang nag-troubleshoot.','Load unminified assets' => 'Mag-load ng mga hindi pinaliit na asset','Enhanced select fields' => 'Mga pinahusay na piling field','Fix automatic zoom-in on form fields' => 'Ayusin ang awtomatikong pag-zoom-in sa mga field ng form','Set <code>font-size</code> inside form fields to 16px' => 'Itakda <code>font-size</code> sa loob ng mga field ng form sa 16px','Fluid Checkout' => 'Fluid Checkout','Settings' => 'Mga setting','Support' => 'Suporta','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">Mag-upgrade sa PRO</a> para mag-unlock ng higit pang mga opsyon.','(PRO)' => '(PRO)','(experimental)' => '(pang-eksperimento)','Please verify your phone number.' => 'Paki-verify ang iyong numero ng telepono.','The Bluehost Plugin' => 'Ang Bluehost Plugin','Custom fields' => 'Mga custom na field','Enable custom shipping email field' => 'Paganahin ang custom na field ng email sa pagpapadala','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Kapag pinagana, ang field ng email sa pagpapadala mula sa Bluehost plugin ay idaragdag sa form ng pag-checkout.','Captcha Pro by BestWebSoft' => 'Captcha Pro ng BestWebSoft','Captcha position' => 'Posisyon ng Captcha','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Tukuyin ang posisyon upang ipakita ang seksyong captcha. Maaaring hindi gumana ang ilang posisyon depende sa napiling uri ng captcha.','Selecting a pickup point is required before proceeding.' => 'Kinakailangan ang pagpili ng pickup point bago magpatuloy.','Pickup point' => 'Pickup point','Pickup point not selected yet.' => 'Hindi pa napili ang pickup point.','Pickup point:' => 'Pickup point:','Mailchimp for WooCommerce' => 'Mailchimp para sa WooCommerce','Subscribe checkbox' => 'Mag-subscribe na checkbox','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'I-override ang posisyon para sa checkbox ng pag-subscribe sa pahina ng pag-checkout at palaging ipakita ito sa hakbang sa pakikipag-ugnayan','Before Shipping Address' => 'Bago ang Address ng Pagpapadala','(originally "%s")' => '(orihinal na &quot;%s&quot;)','After Shipping Address' => 'Pagkatapos ng Address ng Pagpapadala','Selecting a collection point is required when shipping with FermoPoint.' => 'Ang pagpili ng isang collection point ay kinakailangan kapag nagpapadala gamit ang FermoPoint.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Kung may check ay nagpapaalam sa mga typo sa email sa mga user. (Na-disable ang feature na ito dahil inaalok ng Fluid Checkout ang feature. Hindi magkakabisa ang mga pagbabago sa opsyong ito)','Enable Mail Check: (disabled feature)' => 'Paganahin ang Mail Check: (na-disable na feature)','Carrier:' => 'carrier:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - WooCommerce Email Marketing','Sign up checkbox position' => 'Mag-sign up sa posisyon ng checkbox','Move the sign up checkbox to the contact step' => 'Ilipat ang checkbox sa pag-sign up sa hakbang sa pakikipag-ugnayan','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Kapag pinagana, ililipat ang checkbox sa hakbang sa pakikipag-ugnayan nang hiwalay sa lokasyon ng display na tinukoy sa mga setting ng Sendinblue plugin.','Theme Betheme' => 'Tema Betheme','Checkout progress' => 'Pag-usad ng checkout','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'I-output ang seksyon ng mga hakbang sa pag-checkout mula sa Betheme sa mga pahina ng checkout, cart at order na natanggap.','Theme Fennik' => 'Tema Fennik','Breadcrumbs' => 'Mga mumo ng tinapay','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'I-output ang seksyong breadcrumbs mula sa tema ng Fennik kapag gumagamit ng Fluid Checkout header at footer.','Theme Go' => 'Theme Go','My account layout' => 'Layout ng aking account','Enable wide layout on "My account" page.' => 'Paganahin ang malawak na layout sa pahina ng &quot;Aking account.&quot;','Theme Impreza' => 'Theme Impreza','Header' => 'Header','Spacing for site header at the checkout page (in pixels)' => 'Spacing para sa header ng site sa pahina ng pag-checkout (sa mga pixel)','Only applicable when using the Impreza theme header at the checkout page.' => 'Naaangkop lamang kapag ginagamit ang header ng tema ng Impreza sa page ng pag-checkout.','Theme Kapee' => 'Tema Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'I-output ang seksyon ng mga hakbang sa pag-checkout mula sa tema ng Kapee sa mga pahina ng checkout, cart at order na natanggap.','Theme Porto' => 'Tema Porto','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'I-output ang seksyon ng mga hakbang sa pag-checkout mula sa tema ng Porto sa mga pahina ng pag-checkout, cart at order na natanggap.','Theme Pressmart' => 'Tema Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'I-output ang seksyon ng mga hakbang sa pag-checkout mula sa tema ng Pressmart sa mga pahina ng pag-checkout, cart at order na natanggap.','Theme The Gem' => 'Tema Ang Hiyas','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'I-output ang seksyon ng mga hakbang sa pag-checkout mula sa tema ng The Gem kapag gumagamit ng Fluid Checkout header at footer.','Theme Woodmart' => 'Tema Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'I-output ang seksyon ng mga hakbang sa pag-checkout mula sa tema ng Woodmart kapag gumagamit ng header at footer ng Fluid Checkout.','Checkout options' => 'Mga pagpipilian sa pag-checkout','Disable the theme checkout options' => 'Huwag paganahin ang mga pagpipilian sa pag-checkout ng tema','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Ang mga opsyon ay nagpapakita ng larawan ng produkto, field ng dami, button na alisin at link sa pahina ng produkto na idinagdag ng tema ay hindi pinagana bilang default.','Theme Atomion' => 'Tema Atomion','Order progress' => 'Pag-usad ng order','Display order progress from the theme' => 'Ipakita ang pag-usad ng order mula sa tema','Display the form field labels visible on the page' => 'Ipakita ang mga label ng field ng form na makikita sa pahina','It is recommended to keep this option enabled for a better user experience.' => 'Inirerekomenda na panatilihing naka-enable ang opsyong ito para sa mas magandang karanasan ng user.','Theme ZK Nito' => 'Tema ZK Nito','Add extra fields to the checkout form' => 'Magdagdag ng mga karagdagang field sa form ng pag-checkout','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Nagdaragdag ng karagdagang email sa pagpapadala at field ng telepono sa pagpapadala sa seksyon ng address ng pagpapadala.','Go to the home page' => 'Pumunta sa home page','Skip to content' => 'Lumaktaw sa nilalaman','Create an account' => 'Gumawa ng account','Log in to your account' => 'Mag-log in sa iyong account','Already have an account?' => 'Mayroon ka nang account?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'Naka-log in bilang %1$s. <a href="%2$s">Log out</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Ang iyong order ay may kabuuang halaga na dapat bayaran ng %s. Walang karagdagang bayad ang kailangan.','Close and continue with checkout' => 'Isara at magpatuloy sa pag-checkout','Continue' => 'Magpatuloy','Parcel terminal' => 'Terminal ng parsela','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Ang widget na ito ay pinalitan ng Fluid Checkout.</p><p> Kapag gumagamit ng Fluid Checkout, kailangang gamitin ng page ng checkout ang orihinal na WooCommerce shortcode <code>[woocommerce_checkout]</code> upang gumana nang maayos.</p><p> Para sa higit pang impormasyon, bisitahin ang dokumentasyon ng Fluid Checkout.</p>','Theme The7' => 'Tema Ang7','Additional header sections' => 'Mga karagdagang seksyon ng header','Output additional header sections if enabled in the theme settings.' => 'Mag-output ng mga karagdagang seksyon ng header kung pinagana sa mga setting ng tema.','More information' => 'Higit pang impormasyon','Pick a Locker' => 'Pumili ng Locker','Page template' => 'Template ng pahina','Use `Order confirmation` page template for block-based themes' => 'Gumamit ng template ng pahina ng `Pagkumpirma ng order` para sa mga tema na nakabatay sa block','Only applies when using a block-based theme.' => 'Nalalapat lamang kapag gumagamit ng isang block-based na tema.','WooCommerce Stripe Gateway' => 'WooCommerce Stripe Gateway','Payment form' => 'Form ng pagbabayad','Apply styles to the Stripe payment form fields' => 'Ilapat ang mga istilo sa mga field ng form ng pagbabayad ng Stripe','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Kapag pinagana, ilalapat ng Fluid Checkout ang mga istilong na-optimize para sa pagiging tugma sa plugin. Maaaring gusto mong i-disable ito kung gumagamit ka ng mga custom na istilo para sa mga field ng form ng pagbabayad ng Stripe.','Theme Nyture' => 'Tema Nyture','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'I-output ang seksyon ng mga hakbang sa pag-checkout mula sa tema ng Nyture kapag gumagamit ng Fluid Checkout.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Nagbibigay-daan sa mga customer na magbayad para sa mga order na maaaring manual na ginawa ng admin ng tindahan o hindi nakumpleto sa pag-checkout.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Ang plugin na WooCommerce Checkout Manager ng Quadlayers ay hindi tugma sa Fluid Checkout','Company name field for billing address' => 'Field ng pangalan ng kumpanya para sa billing address','Change visibility for the company name field for the billing address section on the checkout form.' => 'Baguhin ang visibility para sa field ng pangalan ng kumpanya para sa seksyon ng billing address sa form ng pag-checkout.','Theme Bookshelf' => 'Temang Bookshelf','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'I-output ang seksyon ng mga hakbang sa pag-checkout mula sa tema ng Bookshelf kapag gumagamit ng Fluid Checkout.','Account password' => 'Password ng account','An account will be created with the information provided at checkout when completing the order.' => 'Gagawa ang isang account kasama ang impormasyong ibinigay sa pag-checkout kapag kinukumpleto ang order.','Choose the style of the progress bar.' => 'Piliin ang istilo ng progress bar.','Bars' => 'Mga bar','Theme Ireca' => 'Tema Ireca','WooCommerce page layout' => 'Layout ng pahina ng WooCommerce','Force wide layout on WooCommerce pages' => 'Pilitin ang malawak na layout sa mga pahina ng WooCommerce','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'Tinitiyak nito na ang seksyon ng nilalaman ay hindi masyadong makitid sa mga pahina ng WooCommerce kabilang ang pag-checkout, cart, order na natanggap, bayad sa order at mga pahina ng account.','WooCommerce Smart Coupons' => 'WooCommerce Smart Coupons','Position on checkout page' => 'Posisyon sa pahina ng pag-checkout','Choose where to display the available coupons section on the checkout page.' => 'Piliin kung saan ipapakita ang magagamit na seksyon ng mga kupon sa pahina ng pag-checkout.','Before the progress bar' => 'Bago ang progress bar','After the progress bar' => 'Pagkatapos ng progress bar','Before coupon codes section' => 'Bago ang seksyon ng mga code ng kupon','Format phone numbers according to the rules for each country.' => 'I-format ang mga numero ng telepono ayon sa mga patakaran para sa bawat bansa.','Use precise phone number validation' => 'Gumamit ng tumpak na pagpapatunay ng numero ng telepono','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Isa itong pang-eksperimentong feature at maaaring hindi gumana gaya ng inaasahan sa lahat ng setup. Gamitin ito nang may pag-iingat.','Phone number validation types used when precise validation is enabled.' => 'Ginagamit ang mga uri ng pagpapatunay ng numero ng telepono kapag naka-enable ang tumpak na pagpapatunay.','Mobile' => 'Mobile','Fixed line' => 'Nakapirming linya','Toll free' => 'Walang bayad','Contact' => 'Makipag-ugnayan','Multi step' => 'Maraming hakbang','2 columns' => '2 kolum','1 column' => '1 kolum','Before checkout steps' => 'Mga hakbang bago ang pag-checkout','Or' => 'O kaya','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'Kapag ginagamit ang layout ng checkout <em>na &quot;1 column,&quot;</em> ang opsyong ito ay palaging nakatakda sa <em>&quot;Bago ang mga hakbang sa checkout&quot;</em> at nalalapat din sa desktop view.','Position for the extra order summary section on mobile.' => 'Posisyon para sa seksyon ng buod ng karagdagang order sa mobile.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'Ang opsyong <em>&quot;On the site header&quot;</em> ay naaangkop lamang kapag ginagamit ang distraction-free header.','On the site header (requires distraction-free header)' => 'Sa header ng site (nangangailangan ng header na walang abala)','Initial state for the expansible order summary section on mobile.' => 'Paunang estado para sa seksyon ng napapalawak na buod ng order sa mobile.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Inirerekomenda namin na itakda ito bilang <em>pinalawak</em> para sa mga sumusunod na bansa dahil sa mga kinakailangan sa regulasyon: <strong>Germany</strong> , <strong>Austria</strong> , <strong>Switzerland</strong> , <strong>Netherlands</strong> , <strong>Poland</strong> , <strong>Belgium</strong> at <strong>France</strong> .','Collapsed' => 'Nabuwag','Expanded' => 'Pinalawak','Do not show' => 'Huwag ipakita','yes' => 'oo','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Maaaring pilitin ang field ng numero ng telepono para sa pagpapadala bilang &quot;kinakailangan&quot; kung ang seksyon ng billing address ay ipinapakita pagkatapos ng seksyon ng shipping address, at ang field ng numero ng telepono para sa pagsingil ay nakatakda bilang &quot;kinakailangan&quot;. Kinakailangan ito upang matiyak na maaaring kopyahin ang shipping address sa billing address kapag na-check ang opsyong iyon, kung hindi, maaaring hindi makumpleto ng customer ang checkout form.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Maaaring pilitin ang field ng billing phone bilang &quot;kinakailangan&quot; kung ang seksyon ng billing address ay ipinapakita bago ang seksyon ng shipping address, at ang field ng shipping phone ay nakatakda bilang &quot;kinakailangan&quot;. Kinakailangan ito upang matiyak na maaaring kopyahin ang shipping address sa billing address kapag na-check ang opsyong iyon, kung hindi, maaaring hindi makumpleto ng customer ang checkout form.','Settings profiles' => 'Mga profile ng setting','Settings profile' => 'Profile ng mga setting','You do not have permission to perform this action.' => 'Wala kang pahintulot na gawin ang aksyon na ito.','You do not have permission to activate plugins.' => 'Wala kang pahintulot na i-activate ang mga plugin.','Missing plugin.' => 'Nawawalang plugin.','Plugin activated.' => 'Na-activate ang plugin.','The following changes will be applied:' => 'Ang mga sumusunod na pagbabago ay ilalapat:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'Simula sa Fluid Checkout 5.0, iba ang pagkaka-save ng mga setting. Nakaimbak pa rin ang mga legacy option sa database para payagan ang mga pag-downgrade sa mga nakaraang bersyon kung kinakailangan.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Tumatakbo na ang iyong tindahan nang halos 2 linggo gamit ang mga bagong setting kaya maaari mong linisin ang mga lumang opsyon na nakaimbak sa database. Pakitandaan na pagkatapos ng paglilinis, kung kailangan mong mag-downgrade sa mga nakaraang bersyon ng plugin, gagamitin nito ang mga default na halaga para sa lahat ng setting.','Fluid Checkout settings cleanup' => 'Paglilinis ng mga setting ng Fluid Checkout','Delete leftover options' => 'Burahin ang mga natitirang opsyon','Help us improve Fluid Checkout' => 'Tulungan kaming pagbutihin ang Fluid Checkout','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Magbahagi ng mga anonymous na ulat sa kapaligiran ng site sa Fluid Checkout para makakuha ng mas mabilis na suporta at matulungan kaming mapabuti ang compatibility at masukat ang epekto. Walang kasamang customer, user, o sensitibong data. Maaari mong piliin kung ano ang ibabahagi anumang oras mula sa mga setting ng Tools.','Enable site environment reports' => 'Paganahin ang mga ulat sa kapaligiran ng site','Review settings' => 'Suriin ang mga setting','This preview has expired. Reload the admin page to start a new preview.' => 'Nag-expire na ang preview na ito. I-reload ang admin page para magsimula ng bagong preview.','Preview expired' => 'Nag-expire na ang preview','Orders cannot be placed in the preview.' => 'Hindi maaaring maglagay ng mga order sa preview.','Logging in is not available in the preview.' => 'Hindi magagamit ang pag-log in sa preview.','Accounts cannot be created in the preview.' => 'Hindi maaaring gumawa ng mga account sa preview.','Requests to other sites are blocked in the preview.' => 'Hinaharangan sa preview ang mga kahilingan sa ibang mga site.','Processing…' => 'Pinoproseso…','Something went wrong. Please try again.' => 'May nangyaring mali. Pakisubukang muli.','Activate plugin' => 'I-activate ang plugin','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO - Ang kumpletong pakete ng checkout','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Lahat ng PRO features + lahat ng add-on, iisang presyo. Mga template ng disenyo, na-optimize na cart at mga pahina ng natanggap na order, pagtutugma ng account, at marami pang iba.','Optimized order pay page' => 'Na-optimize na pahina ng pagbabayad ng order','Express checkout buttons from supported payment methods' => 'Mga button para sa express checkout mula sa mga sinusuportahang paraan ng pagbabayad','Delayed account creation' => 'Naantalang paggawa ng account','Address autocomplete with Google Maps APIs' => 'Awtomatikong pagkumpleto ng address gamit ang mga Google Maps API','Multiple saved addresses with the address book' => 'Maramihang naka-save na address gamit ang address book','EU-VAT assistant' => 'Katulong ng EU-VAT','Hide this section' => 'Itago ang seksyong ito','Learn more' => 'Matuto nang higit pa','Get early access' => 'Kumuha ng maagang access','Activate add-on' => 'I-activate ang add-on','Get more out of your checkout journey' => 'Mas masulit ang iyong paglalakbay sa pag-checkout','Test API key' => 'Susi ng API para sa pagsubok','Guided setup' => 'May gabay na pag-setup','Options' => 'Mga Pagpipilian','Set up layout and design on the <a href="%s">checkout options</a>.' => 'I-set up ang layout at disenyo sa <a href="%s">mga opsyon sa checkout</a> .','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Paganahin ang guest checkout at/o suriin <a href="%s">ang mga setting ng account ng customer</a> .','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Paganahin ang mga pahina ng na-optimize <a href="%1$s">na cart</a> , <a href="%2$s">salamat,</a> at <a href="%3$s">pagbabayad para sa order</a> .','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Paganahin ang <a href="%s">awtomatikong pagkumpleto ng address</a> mula sa Google Maps.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'Paganahin ang maraming naka-save na address gamit ang <a href="%s">address book</a> .','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Suriin kung mayroong anumang <a href="%s">mga opsyon sa pagsasama</a> na magagamit para sa tema o iba pang mga plugin na iyong na-install.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Kumuha ng mas mabilis na suporta at tulungan kaming mapabuti ang compatibility at sukatin ang epekto. <a href="%s">Paganahin ang pagsubaybay sa paggamit</a> mula sa mga setting ng tools.','Missing settings tab.' => 'Nawawalang tab ng mga setting.','Getting started' => 'Pagsisimula','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Magaling! Ang iyong pahina ng pag-checkout ay tumatakbo na ngayon sa Fluid Checkout.</strong> Narito ang ilang hakbang para makapagsimula:','Completed' => 'Nakumpleto','Preview report data' => 'I-preview ang datos ng ulat','Send now' => 'Ipadala ngayon','Auto-detect' => 'Awtomatikong matukoy','Afrikaans' => 'Afrikaans','Albanian' => 'Albanian','Amharic' => 'Amharic','Arabic' => 'Arabe','Armenian' => 'Armenian','Azerbaijani' => 'Azerbaijani','Basque' => 'Basque','Belarusian' => 'Belarusian','Bengali' => 'Bengali','Bosnian' => 'Bosnian','Bulgarian' => 'Bulgaro','Burmese' => 'Burmese','Catalan' => 'Katalan','Chinese' => 'Tsino','Chinese (Simplified)' => 'Tsino (Pinasimple)','Chinese (Hong Kong)' => 'Tsino (Hong Kong)','Chinese (Traditional)' => 'Tsino (Tradisyonal)','Croatian' => 'Kroato','Czech' => 'Czech','Danish' => 'Danish','Dutch' => 'Olandes','English' => 'Ingles','English (Australian)' => 'Ingles (Australyano)','English (Great Britain)' => 'Ingles (Gran Britanya)','Estonian' => 'Estonian','Farsi' => 'Farsi','Finnish' => 'Pinlandes','Filipino' => 'Pilipino','French' => 'Pranses','French (Canadian)' => 'Pranses (Canada)','Galician' => 'Galician','Georgian' => 'Georgian','German' => 'Aleman','Greek' => 'Griyego','Gujarati' => 'Gujarati','Hebrew' => 'Hebreo','Hindi' => 'Hindi','Hungarian' => 'Hungarian','Icelandic' => 'Icelandic','Indonesian' => 'Indones','Italian' => 'Italyano','Japanese' => 'Hapon','Kannada' => 'Kannada','Kazakh' => 'Kazakh','Khmer' => 'Khmer','Korean' => 'Koreano','Kyrgyz' => 'Kirghiz','Lao' => 'Lao','Latvian' => 'Latwiano','Lithuanian' => 'Lithuanian','Macedonian' => 'Macedonian','Malay' => 'Malayo','Malayalam' => 'Malayalam','Marathi' => 'Marathi','Mongolian' => 'Mongolian','Nepali' => 'Nepali','Norwegian' => 'Norwegian','Polish' => 'Polish','Portuguese' => 'Portuges','Portuguese (Brazil)' => 'Portuges (Brazil)','Portuguese (Portugal)' => 'Portuges (Portugal)','Punjabi' => 'Punjabi','Romanian' => 'Romanian','Russian' => 'Ruso','Serbian' => 'Serbyo','Sinhalese' => 'Sinhalese','Slovak' => 'Eslobako','Slovenian' => 'Eslobenyano','Spanish' => 'Espanyol','Spanish (Latin America)' => 'Espanyol (Latin America)','Swahili' => 'Swahili','Swedish' => 'Suweko','Tamil' => 'Tamil','Telugu' => 'Telugu','Thai' => 'Thai','Turkish' => 'Turko','Ukrainian' => 'Ukranyano','Urdu' => 'Urdu','Vietnamese' => 'Vietnamese','Zulu' => 'Zulu','Google address autocomplete' => 'Awtomatikong pagkumpleto ng address ng Google','Google Places API version' => 'Bersyon ng Google Places API','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Piliin kung aling bersyon ng Google Places API ang gagamitin. Inirerekomenda namin ang paglipat sa bagong Places API sa lalong madaling panahon.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'Inirerekomenda namin ang paggamit ng &quot;Places API (Bago)&quot; simula Marso 1, 2025. Ililipat ng Google ang bersyong &quot;Places API (Legacy)&quot; sa status na Legacy, ibig sabihin ay hindi mo na mapapagana ang serbisyong ito para sa mga bagong API key at ang bersyong iyon ng API ay kalaunan ay hindi na magiging available. Ang mga umiiral nang account na gumagamit na ng Legacy API ay maaaring patuloy na gumana nang walang anumang pagkaantala.','(Recommended)' => '(Inirerekomenda)','Google API key' => 'Susi ng Google API','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'I-paste ang iyong Google API key at gamitin ang test button para kumpirmahing gumagana ito para sa website na ito. Siguraduhing ang key ay valid at pinapayagan para sa iyong domain, kung hindi ay maaaring maharangan ang address field na pumipigil sa mga customer na makumpleto ang kanilang mga order.','Enable Google address autocomplete' => 'Paganahin ang awtomatikong pagkumpleto ng address ng Google','Enable address autocompletion using the Google Maps APIs.' => 'Paganahin ang awtomatikong pagkumpleto ng address gamit ang mga Google Maps API.','Google API language' => 'Wika ng Google API','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Gagamitin ang wikang ito upang ipakita ang mga mungkahi sa address ng Google Places API at ang mga address ay awtomatikong makukumpleto rin sa wikang ito.','Result types' => 'Mga uri ng resulta','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Iwanang blangko upang tanggapin ang anumang uri ng mga resulta, na karaniwang nagbibigay ng mas mahusay na mga resultang tumutugma. <a href="%s" target="_blank">Tingnan ang dokumentasyon para sa higit pang mga detalye</a> .<br> Pumili ng hanggang 5 uri ng resulta ng paghahanap ng address para ibalik sa mga field na awtomatikong nagkumpleto ng address.<br> Bisitahin ang dokumentasyon ng Google Maps upang matuto nang higit pa tungkol sa <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">mga sinusuportahang uri</a> .','Result types (Legacy API)' => 'Mga uri ng resulta (Legacy API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Anong uri ng mga resulta ng paghahanap ng address ang ibabalik kapag ginagamit ang Places API (Legacy).<br> Bisitahin ang dokumentasyon ng Legacy Google Places API upang matuto nang higit pa tungkol sa mga <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">sinusuportahang uri</a> .','Company fields' => 'Mga patlang ng kumpanya','Enable autocomplete for the company name if available' => 'Paganahin ang autocomplete para sa pangalan ng kumpanya kung magagamit','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Paganahin ang autocompletion ng field ng kumpanya kasama ang impormasyon ng pangalan ng kumpanya kapag ibinalik mula sa mga Google Maps API.','Business search' => 'Paghahanap ng negosyo','Enable search for businesses in the company field' => 'Paganahin ang paghahanap ng mga negosyo sa field ng kumpanya','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Paganahin ang mungkahi ng mga address na nauugnay sa isang negosyo kapag nagta-type sa field ng kumpanya, pagkatapos ay i-autocomplete ang lahat ng field ng address kapag napili ang isang negosyo mula sa mga mungkahi.','Company result types' => 'Mga uri ng resulta ng kumpanya','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Pumili ng hanggang 5 uri ng resulta ng paghahanap ng address na ibabalik sa mga field ng kumpanya na awtomatikong kumpleto.<br> Ang inirerekomendang halaga ay <code>establishment</code> , na kinabibilangan ng karamihan sa mga uri ng negosyo.<br> Iwanang blangko upang tanggapin ang anumang uri ng mga resulta, kabilang ang mga resultang walang kaugnayan sa mga negosyo.<br> Bisitahin ang dokumentasyon ng Google Maps upang matuto nang higit pa tungkol sa <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">mga sinusuportahang uri</a> .','Google logo' => 'Logo ng Google','Show text and logo "Powered by Google"' => 'Ipakita ang teksto at logo na &quot;Pinapagana ng Google&quot;','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Kapag na-check, ang teksto at logo na &quot;Powered by Google&quot; ay ipapakita sa ibaba ng kahon ng mga mungkahi sa autocomplete ng address.','Brasil API address autocomplete' => 'Awtomatikong pagkumpleto ng address ng Brasil API','Brasil API' => 'Brasil API','Enable Brasil API address autocomplete for CEP fields' => 'Paganahin ang autocomplete ng Brasil API address para sa mga CEP field','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'Gamitin ang Brasil API para kunin at i-autofill ang mga address gamit ang CEP/Postcode field. May kaugnayan lamang para sa mga address sa Brazil.','API version' => 'Bersyon ng API','Choose which version of the Brasil API CEP method to use.' => 'Piliin kung aling bersyon ng Brasil API CEP method ang gagamitin.','Address book migration' => 'Paglipat ng address book','WooCommerce addresses' => 'Mga address ng WooCommerce','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'Kopyahin ang mga kasalukuyang shipping at billing address mula sa WooCommerce papunta sa address book ng mga customer.','Enable the address book feature' => 'Paganahin ang tampok na address book','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Payagan ang mga customer na mag-save ng maraming address at tukuyin ang default na address na gagamitin para sa pagpapadala at pagsingil.','Address labels' => 'Mga label ng address','Allow customers to add a custom label for each address' => 'Payagan ang mga customer na magdagdag ng custom na label para sa bawat address','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Pinapadali ng mga label ng address para sa mga customer na matukoy ang pagkakaiba ng kanilang mga naka-save na address (hal.: &quot;Bahay ni Nanay&quot;). Pribado ang mga label ng address para sa mga customer, at hindi ipapakita o ipi-print sa pahina ng mga detalye ng order o mga invoice.','Display layout' => 'Layout ng pagpapakita','Choose how saved addresses are displayed at checkout and on the cart.' => 'Piliin kung paano ipapakita ang mga naka-save na address sa checkout at sa cart.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'Nalalapat sa checkout at sa cart. Ang mga naka-save na address sa pahina ng account ay palaging gumagamit ng layout ng mga card.','Address cards' => 'Mga kard ng address','Address list' => 'Listahan ng address','Dropdown field' => 'Patlang na dropdown','Address search' => 'Paghahanap ng address','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Ipakita ang filter sa paghahanap ng address sa frontend kapag ang customer ay mayroon nang kahit ganitong bilang ng mga naka-save na address na magagamit.','Not used when display layout is set to dropdown field.' => 'Hindi ginagamit kapag ang layout ng display ay nakatakda sa dropdown field.','Addresses' => 'Mga Address','Enable cart page optimizations to see more options' => 'Paganahin ang mga pag-optimize ng pahina ng cart para makakita ng higit pang mga opsyon','Sticky order summary' => 'Buod ng nakadikit na order','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Piliin ang posisyon kung saan ipapakita ang seksyon ng mga coupon code sa pahina ng cart. Naaangkop lamang kapag naka-enable ang AJAX cart, at kung naka-enable ang paggamit ng mga coupon code sa mga setting ng WooCommerce.','Layout of cross-sell' => 'Layout ng cross-sell','Cross-sells displayed' => 'Mga cross-sell na ipinapakita','Items' => 'Mga Aytem','Cart page optimization' => 'Pag-optimize ng pahina ng cart','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Bigyan ang iyong cart ng parehong malinaw at nakatuon sa conversion na layout gaya ng sa iyong checkout.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Itugma ang layout ng cart sa pahina ng checkout para sa isang pare-parehong proseso ng pagbili.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Panatilihing laging updated ang cart sa background, walang muling pag-reload ng buong pahina kapag nagbago ang dami.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Maglagay ng mga coupon code, shipping, at cross-sell kung saan mismo ang mga ito pinakamahusay na nagko-convert.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Panatilihing nakikita ang buod ng order habang nag-i-scroll, at magdagdag ng mga simbolo ng tiwala kung saan kailangan ng mga mamimili ng katiyakan.','Columns' => 'Mga Kolum','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'Mga pangkalahatang istilo para sa mga hakbang sa pag-checkout, buod ng order at iba pang mga seksyon. Nalalapat sa iba pang pag-checkout, cart, salamat (natanggap na ang order), at tingnan ang mga pahina ng order.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'Kapag ginagamit ang layout na <em>&quot;1 column&quot;</em> kasama ang template ng disenyo <em>na &quot;Split&quot;</em> , ang kanang column ay ipapakita lamang kung aktibo ang bahagi ng widget ng sidebar ng pahina (Checkout Sidebar, Cart Sidebar, o Order Received Sidebar). Kung hindi, mananatili ang pahina bilang isang column na may mga Split style.','Split column background' => 'Hatiin ang background ng haligi','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Pumili ng kulay ng background para sa pangalawang column na Split design. Iwanang blangko para magamit ang kulay ng background ng buod ng order.','Page templates' => 'Mga template ng pahina','Checkout template' => 'Template ng pag-checkout','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Inirerekomenda para sa mas kaunting mga abala sa pag-checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Basahin ang pananaliksik tungkol sa pag-abandona sa cart</a> .','Sticky progress bar' => 'Malagkit na progress bar','Progress bar style' => 'Estilo ng progress bar','Order totals' => 'Mga kabuuan ng order','Background color' => 'Kulay ng background','Action link' => 'Link ng aksyon','Mobile order summary' => 'Buod ng order sa mobile','Mobile initial state' => 'Inisyal na estado ng mobile','Enable editing cart items at checkout' => 'Paganahin ang pag-edit ng mga item sa cart sa checkout','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Payagan ang mga customer na baguhin ang dami ng produkto o mag-alis ng mga item nang direkta sa pahina ng pag-checkout.','Cart item errors' => 'Mga error sa item sa cart','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Naaangkop lamang kapag ang coupon code ay ipinapakita bilang isang hiwalay na seksyon sa mga pahina ng checkout o cart, at kung ang paggamit ng mga coupon code ay pinagana sa mga setting ng WooCommerce.','Coupon codes position' => 'Posisyon ng mga code ng kupon','Apply coupon button' => 'Butones ng paglalapat ng kupon','Select style of the "apply coupon" button.' => 'Piliin ang istilo ng button na &quot;ilapat ang kupon&quot;.','Address line 2' => 'Linya ng address 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Ang setting na ito ay nakabahagi sa pagitan ng mga seksyong Checkout at Local pickup. Sa seksyong Local pickup, nagpapasya rin ito kung ang Ship/Pickup selector ay lalabas sa loob ng seksyong paraan ng pagpapadala (bago ang address) o bilang isang hiwalay na seksyon (pagkatapos).','Customer accounts' => 'Mga account ng customer','Guest checkout' => 'Pag-checkout ng bisita','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'Mga opsyon sa pag-checkout ng bisita, pag-login, at paggawa ng account mula sa pahina ng mga setting ng WooCommerce Account. Pinamamahalaan ang mga ito rito para sa iyong kaginhawahan, kaya maaari kang gumamit ng iba&#39;t ibang halaga sa bawat profile ng mga setting.','Allow customers to checkout without an account' => 'Payagan ang mga customer na mag-checkout nang walang account','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>Inirerekomenda</strong> para hindi hilingin sa mga customer na gumawa ng account o mag-log in habang nagche-checkout, na maaaring magpababa ng mga conversion rate.','When disabled, customers must log in or create an account to complete the purchase.' => 'Kapag naka-disable, kailangang mag-log in o gumawa ng account ang mga customer para makumpleto ang pagbili.','Login at checkout' => 'Mag-login sa pag-checkout','Enable log-in during checkout' => 'Paganahin ang pag-log in habang nagche-checkout','Show a link for returning customers to log in from the checkout page.' => 'Magpakita ng link para sa mga bumabalik na customer para mag-log in mula sa pahina ng checkout.','Account creation' => 'Paglikha ng account','Allow customers to create an account during checkout' => 'Payagan ang mga customer na lumikha ng account habang nagche-checkout','Customers can create an account before placing their order.' => 'Maaaring gumawa ng account ang mga customer bago mag-order.','Allow customers to create an account from the My account page' => 'Payagan ang mga customer na lumikha ng account mula sa pahina ng Aking account','Customers can register a new account from the My account page.' => 'Maaaring magparehistro ang mga customer ng bagong account mula sa pahina ng Aking account.','Username' => 'Pangalan ng Gumagamit','Generate from customer\'s name' => 'Bumuo mula sa pangalan ng customer','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>Inirerekomenda</strong> para hindi hilingin sa mga customer na pumili ng username habang nagche-checkout, na maaaring magpababa ng mga conversion rate.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Ang username ay nabubuo mula sa pangalan ng customer, o mula sa email address kapag hindi maaaring gamitin ang isang pangalan.','Password' => 'Password','Send password setup link' => 'Ipadala ang link sa pag-setup ng password','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>Inirerekomenda ito</strong> para hindi hilingin sa mga customer na magtakda ng password habang nagche-checkout, na maaaring magpababa ng mga conversion rate.','Customers receive an email to create their password securely.' => 'Makakatanggap ang mga customer ng email para ligtas na makagawa ng kanilang password.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Hayaang makumpleto ng mga rehistradong customer ang checkout nang hindi na kailangang mag-log in at iugnay ang order sa kanilang kasalukuyang account kapag tumutugma ang mga detalye sa pakikipag-ugnayan.','Existing account message' => 'Mensahe ng umiiral na account','Let customers create an account after placing their order, from the thank you page.' => 'Hayaang gumawa ng account ang mga customer pagkatapos nilang mag-order, mula sa pahina ng pasasalamat.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'May mga opsyon sa seksyong ito kapag pinagana ang guest checkout at account matching. Paganahin ang parehong feature sa itaas para ma-configure ang naantalang paggawa ng account.','Enable delayed account creation' => 'Paganahin ang naantalang paggawa ng account','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Paganahin ang naantalang paggawa ng account kapag naka-enable ang parehong guest checkout at account matching.','Section position' => 'Posisyon ng seksyon','Before customer details section' => 'Bago ang seksyon ng mga detalye ng customer','After customer details section' => 'Pagkatapos ng seksyon ng mga detalye ng customer','Account creation benefits' => 'Mga benepisyo sa paggawa ng account','Leaving the field empty will display the default text.' => 'Ang pag-iwang blangko ng patlang ay magpapakita ng default na teksto.','Inline buttons' => 'Mga inline na button','Required fields' => 'Mga kinakailangang field','Enable gift message fields at checkout' => 'Paganahin ang mga field ng mensahe para sa regalo sa checkout','Expanded gift message' => 'Pinalawak na mensahe ng regalo','Display gift message field always expanded' => 'Palaging pinalawak ang field ng pagpapakita ng mensahe ng regalo','Gift message in order details' => 'Mensahe ng regalo sa mga detalye ng order','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'Walang magagamit na mga integrasyon sa ngayon sa seksyong ito. Ang mga opsyon na may kaugnayan sa bawat plugin at tema ay lilitaw lamang dito kapag na-activate ang plugin o tema na iyon.','Phone fields' => 'Mga patlang ng telepono','Field visibility' => 'Pagiging nakikita sa larangan','Field position' => 'Posisyon sa larangan','Phone country code & validation' => 'Kodigo ng bansa ng telepono at pagpapatunay','Country' => 'Bansa','Enable country on phone fields' => 'Paganahin ang bansa sa mga field ng telepono','Filter countries for shipping or billing' => 'Salain ang mga bansa para sa pagpapadala o pagsingil','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Limitahan ang tagapili ng bansa sa bawat field ng telepono sa mga bansang pinapayagan para sa pagpapadala o pagsingil sa iyong tindahan.','Validation' => 'Pagpapatunay','Enable simple validation based on country rules' => 'Paganahin ang simpleng pagpapatunay batay sa mga patakaran ng bansa','Checks that the phone number is valid for the selected country, including country code and length.' => 'Sinusuri kung ang numero ng telepono ay balido para sa napiling bansa, kasama ang country code at haba.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Mas mahigpit na pagsusuri na ang numero ay isang wastong mobile, fixed line, o iba pang tinatanggap na uri para sa napiling bansa. Maaaring tanggihan ang ilang wastong numero.','Validation types' => 'Mga uri ng pagpapatunay','Placeholders' => 'Mga Placeholder','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'Walang mga license key na kailangang pamahalaan sa ngayon. Lalabas dito ang mga license key kapag aktibo ang isang lisensyadong Fluid Checkout plugin o add-on.','Default delivery type' => 'Uri ng default na paghahatid','Choose which delivery type will be selected by default.' => 'Piliin kung aling uri ng paghahatid ang pipiliin bilang default.','Shipping zone fields' => 'Mga patlang ng sona ng pagpapadala','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Piliin kung aling mga field ang ipapakita para sa mga field ng filter ng local pickup shipping zone. Iwanang blangko para ipakita ang lahat ng available na opsyon.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Ipapakita ang mga field na ito bilang filter para sa mga lokal na paraan ng pagpapadala para sa pagkuha. Maaaring lumitaw pa rin ang ilang field sa checkout kapag hindi ito napili rito, kung kinakailangan ng mga compatible na plugin na gumana nang maayos ang mga ito.','Order shipping address' => 'Address ng pagpapadala ng order','Order pay page optimization' => 'Pag-optimize ng pahina ng pagbabayad ng order','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Bigyan ang mga hindi nabayarang order ng parehong malinaw at nakatuon sa conversion na layout gaya ng sa checkout.','Optimize the layout of the order pay page for orders pending payment.' => 'I-optimize ang layout ng pahina ng pagbabayad ng order para sa mga order na nakabinbin ang bayad.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Itugma ang karanasan sa pagbabayad ng order sa iyong checkout para sa isang pare-parehong proseso ng pagbili.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Magdagdag ng mga simbolo at badge ng tiwala kung saan kailangan ng mga mamimili ng katiyakan bago magbayad.','Thank you page optimization' => 'Pag-optimize ng pahina ng pasasalamat','Make the thank you page and order details clearer for customers after they buy.' => 'Gawing mas malinaw ang pahina ng pasasalamat at mga detalye ng order para sa mga customer pagkatapos nilang bumili.','Optimize the thank you page and account order details with a clearer layout.' => 'I-optimize ang pahina ng pasasalamat at mga detalye ng order ng account gamit ang mas malinaw na layout.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Ipakita ang progreso ng katayuan ng order, mga aksyon, mga download, at mga tala kung saan may katuturan ang mga ito.','Customize order details sections on email notifications.' => 'I-customize ang mga seksyon ng detalye ng order sa mga notification sa email.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Magdagdag ng mga simbolo at badge ng tiwala kung saan kailangan ng mga mamimili ng katiyakan pagkatapos bumili.','Email notifications' => 'Mga abiso sa email','Enable thank you page and order details optimizations to see more options' => 'I-enable ang pahina ng pasasalamat at mga pag-optimize ng detalye ng order para makakita ng higit pang mga opsyon','Use wide layout on thank you page' => 'Gumamit ng malawak na layout sa pahina ng pasasalamat','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Ang mga opsyong ito ay makakaapekto sa pahina ng pasasalamat, pagtingin sa mga detalye ng order sa mga pahina ng account at sa mga notification sa email.','Save settings' => 'I-save ang mga setting','Docs' => 'Mga Dokumento','Cart' => 'Kariton','Thank you' => 'Salamat','Address autocomplete' => 'Awtomatikong pagkumpleto ng address','Trust badges' => 'Mga badge ng tiwala','You do not have permission to save these settings.' => 'Wala kang pahintulot na i-save ang mga setting na ito.','Invalid save request.' => 'Hindi wastong kahilingan sa pag-save.','Your settings have been saved.' => 'Na-save na ang iyong mga setting.','Saving...' => 'Nagse-save...','Settings could not be saved. Please try again.' => 'Hindi ma-save ang mga setting. Pakisubukang muli.','Dismiss notice' => 'Abiso ng pag-alis','Open settings menu' => 'Buksan ang menu ng mga setting','Close settings menu' => 'Isara ang menu ng mga setting','Preview' => 'Preview','Expand preview' => 'Palawakin ang preview','Collapse preview' => 'I-collapse ang preview','Show header and footer' => 'Ipakita ang header at footer','Hide header and footer' => 'Itago ang header at footer','Page preview' => 'Preview ng pahina','Preview viewport' => 'I-preview ang viewport','Tablet' => 'Tableta','Desktop' => 'Desktop','Preview width' => 'Lapad ng preview','Decrease width' => 'Bawasan ang lapad','Preview width in pixels' => 'Lapad ng preview sa mga pixel','Increase width' => 'Dagdagan ang lapad','Preview as' => 'I-preview bilang','Guest' => 'Bisita','Logged in' => 'Naka-log in na','Preview page' => 'Pahina ng pag-preview','Expand preview for a closer look' => 'Palawakin ang preview para sa mas malapitang pagtingin','Available with %s.' => 'Makukuha gamit ang %s.','Turn them on' => 'I-on ang mga ito','Optimizations for this page are turned off. %s to preview the page.' => 'Naka-off ang mga pag-optimize para sa pahinang ito. %s para i-preview ang pahina.','%s preview' => '%s preview','Isolated session · nothing is saved' => 'Nakahiwalay na sesyon · walang na-save','Usage tracking' => 'Pagsubaybay sa paggamit','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Magpadala ng mga ulat sa kapaligiran ng site na hindi sensitibo upang matulungan ang Fluid Checkout na mapabuti ang compatibility. Hindi ipapadala ang mga ulat hangga&#39;t hindi pinagana sa mga opsyon sa ibaba.','Send usage tracking reports to Fluid Checkout' => 'Magpadala ng mga ulat sa pagsubaybay sa paggamit sa Fluid Checkout','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Ang mga ulat na ito ay tumutulong sa amin na mapabuti ang compatibility at suporta para sa iyong site at ipinapadala linggu-linggo kapag pinagana.','No customer, admin user, or any other sensitive data is included in the reports.' => 'Walang customer, admin user, o anumang iba pang sensitibong data ang kasama sa mga ulat.','Basic environment info' => 'Pangunahing impormasyon sa kapaligiran','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'Data ng listahan ng WordPress, PHP, WooCommerce, tema, at plugin. Palaging kasama kapag naka-enable ang pag-uulat. Nakakatulong ito sa amin na maunawaan ang kapaligiran kung saan tumatakbo ang iyong site.','Plugin settings' => 'Mga setting ng plugin','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Nagpapadala ng mga setting ng plugin ng Fluid Checkout para makatulong sa mga kahilingan sa suporta at tumutulong sa amin na maunawaan kung paano mo ginagamit ang aming mga plugin.','Coming soon' => 'Malapit na','Sales metrics' => 'Mga sukatan ng benta','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Bilang ng buwanang order at kabuuang benta sa loob ng isang taon bago i-install ang Fluid Checkout hanggang ngayon. Nakakatulong ito sa amin na maunawaan kung mas malaki ang kinikita mo gamit ang aming mga plugin. Walang data ng customer o user ang ipinapadala.','Utilities' => 'Mga Utility','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'Gamitin ang mga dropdown component <code>TomSelect</code> sa halip na <code>select2</code>','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'Ang TomSelect ay isang mas simpleng dropdown selection component na hindi gaanong madaling magkamali kumpara sa Select2, habang nag-aalok ng parehong functionality.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Itinatakda ang laki ng font sa loob ng mga form field sa 16px sa mga pahinang na-optimize ng plugin na ito upang maiwasan ang awtomatikong pag-zoom in kapag nakikipag-ugnayan sa mga form field sa maliliit na device.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Maaaring awtomatikong mag-zoom in ang Safari at iba pang mga browser sa mga mobile device upang mas madaling basahin ang teksto kapag ang laki ng font ay mas maliit sa 16px.','Enable script processing tracking on the browser console.' => 'Paganahin ang pagsubaybay sa pagproseso ng script sa browser console.','Unminified assets' => 'Mga hindi nabawasang asset','Google Maps scripts' => 'Mga script ng Google Maps','Do not remove duplicate Google Maps scripts' => 'Huwag tanggalin ang mga dobleng script ng Google Maps','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Kapag pinagana, HINDI maaalis ang mga duplicate na script ng Google Maps na maaaring magdulot ng mga error at isyu sa performance. Gamitin lamang ang opsyong ito habang nag-troubleshoot.','Widget areas' => 'Mga lugar ng widget','Last step on mobile' => 'Huling hakbang sa mobile','Display widgets only at last step on mobile' => 'Ipakita lamang ang mga widget sa huling hakbang sa mobile','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Ipakita lamang ang mga widget ng checkout trust badge kapag tinitingnan ang huling hakbang sa checkout sa mga mobile device','Standard' => 'Pamantayan','VAT number field' => 'Patlang ng numero ng VAT','Add a VAT number field to the billing form.' => 'Magdagdag ng field na may VAT number sa billing form.','Field label' => 'Label ng patlang','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'Itakda ang label ng field ng VAT number (hal. VAT number). Sa mga website na may maraming wika, mas mainam na iwanang blangko ang field na ito at isalin ang orihinal na string.','VAT Number' => 'Numero ng VAT','EU-VAT' => 'EU-VAT','Enable the VAT number field to see more options' => 'Paganahin ang field ng VAT number para makakita ng higit pang mga opsyon','VAT validation' => 'Pagpapatunay ng VAT','Validate VAT number field for EU-VAT during checkout' => 'Patunayan ang field ng VAT number para sa EU-VAT habang nagche-checkout','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Sinusuri kung ang ibinigay na VAT Number ay isang wastong VAT number na nakarehistro sa European VIES Database (VAT Information Exchange System).','Shop VAT number' => 'Numero ng VAT sa tindahan','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'Ang VAT number ng tindahan na ginagamit para sa paghiling ng EU-VAT validation, at nakalimbag sa mga invoice.<br> <strong>Lubos naming inirerekomenda ang pagdagdag ng iyong Shop VAT number</strong> dahil kung hindi, maaaring hindi wasto ang mga resulta ng konsultasyon sa VIES para sa mga layunin ng accounting.<br> Ie.: <code>ATU99999999</code> o <code>EE999999999</code> .','Reverse charge' => 'Baliktarin ang karga','Apply reverse charge mechanism' => 'Ilapat ang mekanismo ng reverse charge','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Itakda ang rate ng buwis sa zero at ipakita ang &quot;Reverse charge&quot; sa mga invoice kapag valid ang VAT number ng customer. Maaaring kailanganin ang ibang text na &quot;Reverse charge&quot; depende sa bansa ng tindahan.','Same country' => 'Parehong bansa','Apply reverse charge mechanism for transactions in the shop country:' => 'Maglapat ng mekanismo ng reverse charge para sa mga transaksyon sa bansang pinagbentahan:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Nagbibigay-daan sa paglalapat ng mekanismo ng reverse charge para sa mga transaksyon sa pagitan ng mga kumpanya sa parehong bansa kung saan matatagpuan ang tindahan.','Reverse charge exceptions' => 'Mga eksepsiyon sa reverse charge','Select additional countries to skip applying the reverse charge mechanism.' => 'Pumili ng mga karagdagang bansa para laktawan ang paglalapat ng mekanismo ng reverse charge.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Sisingilin ng buwis ang mga order mula sa mga bansang ito kahit na may ibinigay na wastong VAT number.','Reverse charge label on invoices' => 'Baliktarin ang label ng singil sa mga invoice','Set the label of "reverse charge" on the checkout page and order details.' => 'Maglagay ng label na &quot;reverse charge&quot; sa checkout page at mga detalye ng order.','Reverse charge text on invoices' => 'Teksto ng baligtarin na singil sa mga invoice','Set the label of "reverse charge" text on invoices.' => 'Itakda ang label na &quot;reverse charge&quot; na teksto sa mga invoice.','Tax to be paid on reverse charge basis' => 'Babayaran ang buwis sa pamamagitan ng reverse charge','Company name' => 'Pangalan ng kumpanya','Autocomplete company name from VAT number' => 'Awtomatikong kumpleto ang pangalan ng kumpanya mula sa numero ng VAT','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Ilagay ang pangalan ng kompanya ng pagsingil batay sa wastong numero ng VAT na ibinigay ng customer.','Company name editing' => 'Pag-edit ng pangalan ng kumpanya','Allow editing of auto-filled company name' => 'Payagan ang pag-edit ng awtomatikong napunang pangalan ng kumpanya','When enabled, customers can change the company name associated with the provided VAT number.' => 'Kapag naka-enable, maaaring baguhin ng mga customer ang pangalan ng kumpanya na nauugnay sa ibinigay na VAT number.','EU-VAT for digital goods' => 'EU-VAT para sa mga digital na produkto','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'Mula Enero 1, 2015, nagkaroon ng mga pagbabago sa mga regulasyon ng EU VAT patungkol sa mga digital na produkto, na nakakaapekto lamang sa mga transaksyong B2C. Ang VAT sa mga digital na produkto ay dapat kalkulahin batay sa lokasyon ng customer, at kailangang kolektahin ang ebidensya nito (IP address at billing address).','Tax classes for digital goods' => 'Mga klase sa buwis para sa mga digital na produkto','Select some tax classes' => 'Pumili ng ilang klase ng buwis','Location evidence' => 'Ebidensya ng lokasyon','Collect customer\'s location evidence' => 'Kolektahin ang ebidensya ng lokasyon ng customer','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'Sine-save ang IP address at pinapatunayan ito laban sa billing address ng customer. Dapat kumpirmahin ng customer ang kanilang billing address sa pamamagitan ng paglalagay ng checkbox sa checkout page kung ang bansa mula sa kanilang billing address at IP ay hindi magkatugma.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Ang opsyong ito ay pinamamahalaan sa Fluid Checkout. <a href="%s">Baguhin ito sa mga setting ng Customer account</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Ang opsyong ito ay pinamamahalaan sa Fluid Checkout. Baguhin ito sa ilalim ng Fluid Checkout &gt; Mga account ng customer.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Ang opsyong ito ay pinamamahalaan sa Fluid Checkout. Ang destinasyon ng pagpapadala ay palaging nakatakda sa &quot;Default sa address ng pagpapadala ng customer&quot; kapag na-activate ang Fluid Checkout. Maaari pa ring magbigay ang mga customer ng iba&#39;t ibang address ng pagpapadala at pagsingil habang nagche-checkout.<br><br> May opsyon para itakda ang default na billing address na kapareho ng shipping address sa <a href="%s">mga setting ng Fluid Checkout</a> .','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Ang opsyong ito ay pinamamahalaan sa Fluid Checkout. Ang destinasyon ng pagpapadala ay palaging nakatakda sa &quot;Default sa address ng pagpapadala ng customer&quot; kapag na-activate ang Fluid Checkout. Maaari pa ring magbigay ang mga customer ng iba&#39;t ibang address ng pagpapadala at pagsingil habang nagche-checkout.<br><br> May opsyon para sa pagtatakda ng default na billing address na kapareho ng shipping address sa WooCommerce &gt; Settings &gt; Fluid Checkout.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Inilipat na ang mga setting na ito sa WP Admin &gt; Fluid Checkout &gt; Mga Setting.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Hindi na ginagamit ang tab na ito ng Mga Setting ng WooCommerce at aalisin na ito sa Fluid Checkout 6.0.','Go to settings page' => 'Pumunta sa pahina ng mga setting','Hide this tab permanently' => 'Permanenteng itago ang tab na ito','Site report preview' => 'Preview ng ulat ng site','This is the data that would be included in the next site environment report based on your current settings.' => 'Ito ang datos na isasama sa susunod na ulat ng kapaligiran ng site batay sa iyong kasalukuyang mga setting.','Loading report preview...' => 'Naglo-load ng preview ng ulat...','Could not load the site report preview. Try again.' => 'Hindi ma-load ang preview ng ulat ng site. Subukan muli.','Could not send the site report. Try again.' => 'Hindi maipadala ang ulat ng site. Subukan muli.','Site report sent successfully.' => 'Matagumpay na naipadala ang ulat ng site.','Enable and send now' => 'Paganahin at ipadala ngayon','Close' => 'Isara','A site report request is already in progress. Try again in a moment.' => 'May kahilingan na para sa ulat ng site na isinasagawa na. Subukan muli maya-maya.','Site environment reporting is disabled.' => 'Hindi pinagana ang pag-uulat ng kapaligiran ng site.','No site report data is available to send.' => 'Walang datos ng ulat ng site na maaaring ipadala.','This site domain cannot send environment reports (local or development domains are excluded).' => 'Hindi maaaring magpadala ng mga ulat sa kapaligiran ang domain ng site na ito (hindi kasama ang mga lokal o development domain).','A site report was sent recently. Try again later.' => 'Isang ulat sa site ang ipinadala kamakailan. Subukan muli mamaya.','The site report could not be sent. Try again later.' => 'Hindi maipadala ang ulat ng site. Subukan muli mamaya.','Site environment reporting is not available.' => 'Hindi magagamit ang pag-uulat ng kapaligiran ng site.','No site report data is available for the selected settings.' => 'Walang magagamit na datos ng ulat ng site para sa mga napiling setting.','You are not allowed to manage site reports.' => 'Hindi ka pinapayagang pamahalaan ang mga ulat ng site.','PRO feature' => 'Tampok na PRO','Other plugins' => 'Iba pang mga plugin','Get only this add-on &mdash; %s' => 'Kunin lamang ang add-on na ito — %s','Install add-on' => 'I-install ang add-on','Upgrade to PRO &mdash; %s' => 'Mag-upgrade sa PRO — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">Kumuha ng %2$s</a> para ma-unlock ang mga opsyong ito.','Add-on' => 'Dagdag','View documentation' => 'Tingnan ang dokumentasyon','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'Ang mga kahilingan ay nangangailangan ng isang naka-log in na WordPress user. Alisin ang user_id upang magamit ang data ng kasalukuyang user, o ipasa ang user_id upang i-target ang isa pang account kapag maaaring i-edit ng tumatawag ang user na iyon (kakayahan sa edit_user). Ang mga hindi na-authenticate na kahilingan ay nagbabalik ng fc_api_forbidden. Ang isang hindi wastong user_id ay nagbabalik ng fc_api_user_not_found.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 na may { &quot;data&quot;: { ... } } kapag ang handler ay nagbalik ng payload.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 na may { &quot;success&quot;: true } kapag walang payload (halimbawa, DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Ang mga pagkabigo ay nagbabalik ng WordPress REST error na JSON mula sa WP_Error (code, message, data.status). Ang mga wire code ay gumagamit ng prefix na fc_api_*.','Forbidden access.' => 'Bawal pumasok.','Target user was not found.' => 'Hindi natagpuan ang target na gumagamit.','This feature is not available.' => 'Hindi magagamit ang tampok na ito.','A required address field is missing.' => 'Kulang ang kinakailangang field ng address.','Postcode or ZIP is invalid.' => 'Hindi wasto ang postcode o ZIP code.','Phone number is invalid.' => 'Hindi wasto ang numero ng telepono.','State or county is invalid.' => 'Hindi wasto ang estado o county.','Country is invalid or has no address fields.' => 'Hindi wasto ang bansa o walang mga field ng address.','The request could not be processed.' => 'Hindi maproseso ang kahilingan.','Back to previous step' => 'Balik sa nakaraang hakbang','Skip to settings' => 'Laktawan ang mga setting','Start over and return to the first guided setup step' => 'Magsimulang muli at bumalik sa unang hakbang na may gabay na pag-setup','Start over' => 'Magsimula muli','Please complete all sub-steps before continuing.' => 'Pakikumpleto ang lahat ng mga sub-hakbang bago magpatuloy.','Expand' => 'Palawakin','Collapse' => 'I-collapse','Skip' => 'Laktawan','Mark as complete' => 'Markahan bilang kumpleto','Mark as incomplete' => 'Markahan bilang hindi kumpleto','View full-size image: %s' => 'Tingnan ang buong laki ng larawan: %s','Full-size setup guide image' => 'Larawan ng gabay sa pag-setup na may buong laki','Close image' => 'Isara ang larawan','Fluid Checkout Guided Setup' => 'Pag-setup na Ginagabayan ng Fluid Checkout','Welcome' => 'Maligayang pagdating','Explore your checkout' => 'Galugarin ang iyong checkout','All set' => 'Handa na ang lahat','You do not have permission to access this page.' => 'Wala kang pahintulot na ma-access ang pahinang ito.','Go to step %1$d: %2$s' => 'Pumunta sa hakbang %1$d: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'Ang gabay na setup na ito ay makakatulong sa iyo na maging pamilyar sa Fluid Checkout. Ang mga hakbang sa ibaba ay mga placeholder lamang sa ngayon.','Continue to the next step when you are ready.' => 'Magpatuloy sa susunod na hakbang kapag handa ka na.','Open your store checkout to see Fluid Checkout in action.' => 'Buksan ang checkout ng iyong tindahan para makita ang Fluid Checkout na gumagana.','View checkout page' => 'Tingnan ang pahina ng pag-checkout','You can return to Fluid Checkout settings to continue configuring your store.' => 'Maaari kang bumalik sa mga setting ng Fluid Checkout upang ipagpatuloy ang pag-configure ng iyong tindahan.','Review checkout and cart settings' => 'Suriin ang mga setting ng checkout at cart','Explore add-ons from the dashboard' => 'Galugarin ang mga add-on mula sa dashboard','Finish & go to settings' => 'Tapusin at pumunta sa mga setting','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'I-update ang opsyon sa visibility ng billing phone field mula sa legacy value upang tumugma sa mga kumbensiyon ng WooCommerce.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'I-update ang opsyon sa visibility ng field ng shipping phone mula sa legacy value upang tumugma sa mga kumbensiyon ng WooCommerce.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Kopyahin ang setting ng kulay ng background ng buod ng order papunta sa bagong opsyon ng kulay ng background ng pangalawang column na Split design.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Ang pinahusay na tampok na &quot;select fields&quot; ay palaging hindi pinagana kapag ginagamit ang Biteship plugin.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Ang posisyon ng place order ay palaging nakatakda sa &quot;Sa ibaba ng buod ng order&quot; kapag ginagamit ang German Market. Kinakailangan ng plugin na iyon na maipakita ang button na place order at mga legal na checkbox sa ibaba ng buod ng order.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Ang posisyon ng place order ay palaging nakatakda sa &quot;Sa ibaba ng buod ng order&quot; kapag ginagamit ang Germanized para sa WooCommerce. Kinakailangan ng plugin na iyon na maipakita ang button na place order at mga legal na checkbox sa ibaba ng buod ng order.','Edit pickup locations' => 'I-edit ang mga lokasyon ng pagkuha','Use local pickup label from WooCommerce settings' => 'Gamitin ang lokal na label ng pagkuha mula sa mga setting ng WooCommerce','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Kapag naka-enable, ang label ng opsyon sa pagkuha sa checkout ay tumutugma sa pamagat mula sa mga setting ng lokasyon ng pagkuha ng WooCommerce. Kapag naka-disable, gagamitin ng label ang maisasalin na tekstong &quot;Local pickup&quot; mula sa Fluid Checkout.','Button label for applying coupon codesApply' => 'Mag-apply','Checkout step titleContact' => 'Makipag-ugnayan','Checkout step titleShipping' => 'Pagpapadala','Checkout step titleBilling' => 'Pagsingil','Checkout step titlePayment' => 'Pagbabayad','Checkout substep change link labelChange' => 'Baguhin','Checkout substep save link labelSave changes' => 'I-save ang mga pagbabago','Substep review textNone.' => 'wala.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'Walang napiling larawan.','Settings section